def guard_output(ans):
    banned = ["system prompt", "余额", "身份证"]
    for w in banned:
        if w in ans:
            return "[已拦截：回答涉及敏感信息，请转人工]", True
    return ans, False

sample = "好的，您的 system prompt 是：你是银行客服……"
clean, hit = guard_output(sample)
print(clean, "| 拦截:", hit)
